insert into public.study_tests(id,title,subject,grade,level,path,questions) values('wirusy-v1','Wirusy','Biologia','2lo','rozszerzony','testy/biologia/wirusy.html','[{"no": 1, "question": "W hodowli znajdują się wiriony oraz pożywka bogata w cukry i aminokwasy, ale nie ma komórek. Dlaczego liczba wirionów nie wzrośnie?", "topic": "Budowa", "options": ["Wirusy potrzebują przede wszystkim wyższej temperatury.", "Wirusy nie mają własnego aparatu do syntezy białek i zależą od komórek.", "Wirusy mogą namnażać się tylko w obecności innych wirusów.", "Pożywka uniemożliwia wirusom podział komórkowy."], "correct": 1, "explanation": "Wirusy nie mają rybosomów ani samodzielnego metabolizmu. Składniki pożywki nie zastąpią aparatu komórkowego gospodarza. Wirusy nie dzielą się jak komórki."}, {"no": 2, "question": "Który zestaw składników występuje w każdym wirionie?", "topic": "Budowa", "options": ["DNA i RNA oraz błona komórkowa.", "RNA oraz osłonka lipidowa.", "Materiał genetyczny i kapsyd.", "DNA oraz rybosomy."], "correct": 2, "explanation": "Wirion zawiera genom w postaci DNA albo RNA oraz białkowy kapsyd. Osłonkę zewnętrzną mają tylko niektóre wirusy; rybosomy nie są składnikiem wirionów."}, {"no": 3, "question": "Wirus uzyskał osłonkę podczas pączkowania z komórki. Skąd pochodzi lipidowa część tej osłonki?", "topic": "Budowa", "options": ["Z fragmentu błony komórki gospodarza.", "Z przekształcenia kapsomerów w lipidy.", "Z materiału genetycznego wirusa.", "Z rybosomów komórki gospodarza."], "correct": 0, "explanation": "Przy pączkowaniu wirus otacza się fragmentem błony gospodarza. W osłonce znajdują się także białka wirusowe, m.in. glikoproteiny."}, {"no": 4, "question": "Zmiana białka powierzchniowego wirusa sprawiła, że nie wiąże się ono z receptorem komórki. Który etap infekcji zostanie bezpośrednio zablokowany?", "topic": "Budowa", "options": ["Składanie wirionów potomnych.", "Translacja białek wirusowych.", "Uwolnienie wirionów potomnych.", "Adsorpcja do powierzchni komórki."], "correct": 3, "explanation": "Adsorpcja oznacza przyłączenie wirusa do odpowiednich receptorów komórki. Brak dopasowania blokuje już pierwszy etap infekcji."}, {"no": 5, "question": "Wirus ma główkę z kapsydem, ogonek i włókna służące do przyłączania do bakterii. Jak sklasyfikujesz jego formę?", "topic": "Budowa", "options": ["Helikalna.", "Bryłowo-spiralna.", "Kulista.", "Bryłowa bez ogonka."], "correct": 1, "explanation": "Opis odpowiada złożonej formie bryłowo-spiralnej bakteriofaga: bryłowej główce oraz spiralnemu ogonkowi."}, {"no": 6, "question": "W typowym cyklu opisanego w podręczniku bakteriofaga T4 do bakterii dostaje się przede wszystkim:", "topic": "Cykle infekcyjne", "options": ["Cały wirion razem z kapsydem i włóknami.", "Sam kapsyd bez genomu.", "Genom wirusa, a kapsyd pozostaje na zewnątrz.", "Osłonka lipidowa bez genomu."], "correct": 2, "explanation": "Bakteriofag T4 wstrzykuje do bakterii DNA. Jego białkowe struktury pozostają na zewnątrz komórki."}, {"no": 7, "question": "Która kolejność opisuje główne etapy produktywnej infekcji?", "topic": "Cykle infekcyjne", "options": ["Adsorpcja → wnikanie → powielanie genomu i synteza białek → składanie → uwalnianie.", "Wnikanie → składanie → adsorpcja → synteza białek → uwalnianie.", "Adsorpcja → uwalnianie → synteza białek → składanie → wnikanie.", "Synteza białek → adsorpcja → składanie → wnikanie → uwalnianie."], "correct": 0, "explanation": "Najpierw wirus przyłącza się do komórki i dostarcza genom. Następnie powstają kopie genomu i białka, z których składane są wiriony potomne; dopiero potem są uwalniane."}, {"no": 8, "question": "DNA faga jest zintegrowane z chromosomem bakterii. Bakteria dzieli się, przekazując to DNA komórkom potomnym, bez produkcji nowych fagów. Co opisano?", "topic": "Cykle infekcyjne", "options": ["Cykl lityczny zakończony lizą.", "Pączkowanie wirusa z bakterii.", "Odwrotną transkrypcję RNA faga.", "Cykl lizogeniczny z obecnością profaga."], "correct": 3, "explanation": "W cyklu lizogenicznym DNA faga wbudowane w genom bakterii nazywamy profagiem. Jest kopiowane razem z DNA gospodarza i przekazywane komórkom potomnym."}, {"no": 9, "question": "Po działaniu czynnika stresowego bakteria zawierająca profaga zaczyna wytwarzać fagi, a następnie pęka. Jakie przejście nastąpiło?", "topic": "Cykle infekcyjne", "options": ["Z cyklu litycznego do lizogenicznego.", "Z cyklu lizogenicznego do litycznego.", "Z translacji do odwrotnej transkrypcji.", "Z infekcji wirusowej do podziału wiriona."], "correct": 1, "explanation": "Indukcja profaga uruchamia cykl lityczny: powstają wiriony potomne, a liza uwalnia je z bakterii."}, {"no": 10, "question": "Zablokowano rybosomy zakażonej komórki, ale nadal możliwe jest kopiowanie wirusowego DNA. Który proces zostanie bezpośrednio zahamowany?", "topic": "Cykle infekcyjne", "options": ["Adsorpcja kolejnych wirusów.", "Replikacja wirusowego DNA.", "Synteza białek wirusowych.", "Wiązanie wirusa z receptorem."], "correct": 2, "explanation": "Na rybosomach zachodzi translacja, czyli synteza białek. Bez białek kapsydu nie powstaną kompletne wiriony, nawet jeśli genom będzie powielany."}, {"no": 11, "question": "Która przemiana jest katalizowana przez odwrotną transkryptazę?", "topic": "Retrowirusy", "options": ["Synteza DNA na matrycy RNA.", "Synteza RNA na matrycy białka.", "Synteza białka na matrycy DNA.", "Synteza RNA na matrycy DNA."], "correct": 0, "explanation": "Odwrotna transkryptaza przepisuje informację z RNA na DNA. Zwykła transkrypcja przebiega w przeciwnym kierunku: DNA → RNA."}, {"no": 12, "question": "Która sekwencja przemian prowadzi od genomu HIV do syntezy białek wirusowych?", "topic": "Retrowirusy", "options": ["RNA → białko → DNA → mRNA.", "RNA → mRNA → DNA → białko.", "DNA → RNA → DNA → białko.", "RNA → DNA → mRNA → białko."], "correct": 3, "explanation": "RNA HIV jest przepisywane na DNA. Po integracji wirusowego DNA z genomem gospodarza transkrypcja wytwarza mRNA, które służy do syntezy białek."}, {"no": 13, "question": "Wirusowe DNA wbudowane w genom komórki zwierzęcej określa się jako:", "topic": "Retrowirusy", "options": ["Kapsomer.", "Prowirus.", "Wirion.", "Receptor."], "correct": 1, "explanation": "Prowirus to wirusowy genom zintegrowany z DNA gospodarza. Profag jest określeniem używanym w przypadku bakteriofagów; kapsomer buduje kapsyd, a wirion jest cząstką wirusa."}, {"no": 14, "question": "Substancja blokuje odwrotną transkryptazę HIV. Jakiego skutku należy oczekiwać bezpośrednio po wniknięciu wirusa?", "topic": "Retrowirusy", "options": ["Nie będzie możliwe wiązanie glikoprotein z receptorem.", "RNA wirusa zostanie przekształcone w białko bez rybosomów.", "Zahamowana zostanie synteza DNA na matrycy wirusowego RNA.", "Powstaną wiriony bez osłonki, ale z prawidłowym DNA."], "correct": 2, "explanation": "Blokada enzymu hamuje etap RNA → DNA, przez co ogranicza dalszy przebieg cyklu. Nie blokuje bezpośrednio wcześniejszej adsorpcji."}, {"no": 15, "question": "Która para poprawnie łączy wirusa z chorobą?", "topic": "Choroby i profilaktyka", "options": ["HPV — rak szyjki macicy.", "HIV — wirusowe zapalenie wątroby A.", "HAV — odra.", "Wirus różyczki — wścieklizna."], "correct": 0, "explanation": "Niektóre typy HPV są związane z rozwojem raka szyjki macicy. HIV może prowadzić do AIDS, HAV wywołuje WZW A, a wirus różyczki wywołuje różyczkę."}, {"no": 16, "question": "Które działanie szczególnie ogranicza szerzenie WZW A drogą pokarmową?", "topic": "Choroby i profilaktyka", "options": ["Używanie wyłącznie sterylnych igieł.", "Unikanie pokąsania przez zwierzęta.", "Ograniczenie kontaktu z osobami kaszlącymi.", "Higiena rąk i bezpieczne przygotowanie żywności."], "correct": 3, "explanation": "HAV szerzy się drogą pokarmową, m.in. przez zanieczyszczenia pochodzące z kału. Higiena oraz bezpieczna żywność ograniczają tę drogę transmisji; profilaktyka obejmuje też szczepienia."}, {"no": 17, "question": "Który zestaw zawiera wyłącznie choroby szerzące się m.in. drogą kropelkową według tabeli w rozdziale?", "topic": "Choroby i profilaktyka", "options": ["WZW A, WZW B, AIDS.", "Grypa, odra, różyczka.", "Wścieklizna, AIDS, WZW C.", "Rak szyjki macicy, WZW A, WZW C."], "correct": 1, "explanation": "W tabeli drogę kropelkową wskazano dla grypy, odry i różyczki. Pozostałe zestawy obejmują choroby związane przede wszystkim z innymi drogami zakażenia."}, {"no": 18, "question": "Dlaczego szczepienie i podanie surowicy odpornościowej działają w różny sposób?", "topic": "Choroby i profilaktyka", "options": ["Szczepionka zawsze zawiera gotowe przeciwciała, a surowica wyłącznie wirusy.", "Oba preparaty działają wyłącznie przez niszczenie rybosomów wirusa.", "Szczepionka pobudza własną odpowiedź odpornościową, a surowica dostarcza gotowe przeciwciała.", "Surowica wbudowuje DNA wirusa w genom, a szczepionka je usuwa."], "correct": 2, "explanation": "Szczepionka dostarcza antygeny pobudzające odporność czynną i pamięć immunologiczną. Surowica dostarcza gotowe przeciwciała, zapewniając odporność bierną, zwykle szybciej, ale krócej."}, {"no": 19, "question": "Dlaczego antybiotyk działający na bakteryjną ścianę komórkową nie hamuje bezpośrednio namnażania wirusa?", "topic": "Znaczenie wirusów", "options": ["Wirus nie ma bakteryjnej ściany komórkowej będącej celem tego antybiotyku.", "Kapsyd wirusa jest zbudowany z tej samej substancji co ściana bakterii.", "Wirus namnaża się wyłącznie poza komórkami, gdzie antybiotyk nie dociera.", "Wszystkie wirusy mają enzym rozkładający każdy antybiotyk."], "correct": 0, "explanation": "Antybiotyk działa na określony cel występujący u bakterii. Wirusy nie mają bakteryjnej ściany komórkowej, więc ten mechanizm nie może bezpośrednio zahamować ich namnażania."}, {"no": 20, "question": "Która sytuacja pokazuje korzystne wykorzystanie wirusów przez człowieka opisane w rozdziale?", "topic": "Znaczenie wirusów", "options": ["Dodanie cukru do pożywki, aby wirusy samodzielnie rosły.", "Wywołanie epidemii wśród roślin uprawnych.", "Zastąpienie przeciwciał wirusowymi rybosomami.", "Zastosowanie bakteriofagów przeciw bakteriom odpornym na wiele antybiotyków."], "correct": 3, "explanation": "Bakteriofagi mogą być wykorzystywane eksperymentalnie do zwalczania bakterii, w tym wieloopornych. Wirusy mogą też regulować liczebność populacji, ale choroby roślin uprawnych powodują straty."}]'::jsonb);
insert into public.study_tests(id,title,subject,grade,level,path,questions) values('tkanki-v1','Tkanki zwierzęce','Biologia','2lo','podstawowy','testy/biologia/tkanki.html','[{"no": 1, "question": "W próbce jelita widać pojedynczą warstwę wysokich komórek z mikrokosmkami i komórkami kubkowymi. Które połączenie funkcji jest najbardziej trafne?", "topic": "Nabłonkowa", "options": ["Mikrokosmki przesuwają śluz, a komórki kubkowe wchłaniają tłuszcze", "Mikrokosmki zwiększają powierzchnię wchłaniania, a komórki kubkowe wydzielają śluz", "Obie struktury służą głównie do przewodzenia impulsów", "Komórki kubkowe wzmacniają kość, a mikrokosmki przesuwają śluz"], "correct": 1, "explanation": "Mikrokosmki zwiększają powierzchnię wchłaniania. Komórki kubkowe wydzielają śluz chroniący i nawilżający powierzchnię."}, {"no": 2, "question": "W uszkodzeniu nabłonka zniszczona zostaje błona podstawna. Jaki skutek jest najbardziej bezpośredni?", "topic": "Nabłonkowa", "options": ["Komórki nabłonka tracą ważne podłoże mocujące je do tkanki leżącej niżej", "Erytrocyty przestają wytwarzać hemoglobinę", "Mięśnie przestają zawierać aktynę", "Chrząstka natychmiast kostnieje"], "correct": 0, "explanation": "Błona podstawna oddziela i mocuje nabłonek do tkanki łącznej pod nim; jest też ważna dla organizacji i odnowy nabłonka."}, {"no": 3, "question": "Gruczoł A oddaje wydzielinę przewodem na powierzchnię skóry. Gruczoł B uwalnia hormon do płynu tkankowego, skąd trafia do krwi. Jak je sklasyfikować?", "topic": "Nabłonkowa", "options": ["A wewnątrzwydzielniczy, B zewnątrzwydzielniczy", "Oba wewnątrzwydzielnicze", "A zewnątrzwydzielniczy, B wewnątrzwydzielniczy", "Oba są tkanką mięśniową"], "correct": 2, "explanation": "Gruczoł zewnątrzwydzielniczy ma przewód wyprowadzający. Wewnątrzwydzielniczy nie ma takiego przewodu; hormony trafiają do krwi po uwolnieniu do otoczenia komórek."}, {"no": 4, "question": "Ścięgno musi wytrzymywać silne rozciąganie głównie w jednym kierunku. Która cecha budowy najlepiej temu odpowiada?", "topic": "Łączna", "options": ["Równolegle ułożone pęczki włókien kolagenowych", "Duże jamki z chondrocytami i brak włókien", "Jedna warstwa komórek nabłonka płaskiego", "Liczne aksony z osłonką mielinową"], "correct": 0, "explanation": "Ścięgno jest przykładem tkanki łącznej zbitej o regularnym układzie włókien kolagenowych, odpornym na rozciąganie wzdłuż ich przebiegu."}, {"no": 5, "question": "Porównujesz chrząstkę i kość. Które zdanie prawidłowo tłumaczy różnicę w ich gojeniu?", "topic": "Łączna", "options": ["Chrząstka jest lepiej ukrwiona niż kość", "Kość ma naczynia krwionośne, a chrząstka nie jest bezpośrednio unaczyniona", "Obie tkanki nie zawierają żywych komórek", "Kość nie ma substancji międzykomórkowej"], "correct": 1, "explanation": "Kość jest unaczyniona. Chrząstka otrzymuje substancje odżywcze drogą dyfuzji, co ogranicza tempo jej regeneracji."}, {"no": 6, "question": "Po urazie stawu uszkodzona zostaje powierzchnia, która zmniejsza tarcie między końcami kości. Która tkanka uległa uszkodzeniu?", "topic": "Łączna", "options": ["Tkanka chrzęstna szklista", "Tkanka nabłonkowa wielowarstwowa", "Tkanka mięśniowa gładka", "Tkanka nerwowa"], "correct": 0, "explanation": "Powierzchnie stawowe pokrywa chrząstka szklista; wraz z mazią pomaga ograniczać tarcie i amortyzować nacisk."}, {"no": 7, "question": "Preparat wykazuje poprzeczne prążkowanie, pojedyncze centralnie położone jądra i połączenia zwane wstawkami. Co to za tkanka?", "topic": "Mięśniowa", "options": ["Mięśniowa szkieletowa", "Mięśniowa gładka", "Mięśniowa serca", "Nabłonkowa jednowarstwowa"], "correct": 2, "explanation": "Komórki mięśnia sercowego są prążkowane, zwykle mają centralne jądro i łączą się wstawkami."}, {"no": 8, "question": "Dlaczego ściana jelita może wykonywać ruchy przesuwające treść bez świadomego sterowania?", "topic": "Mięśniowa", "options": ["Zawiera mięśnie szkieletowe kierowane wolą", "Zawiera tkankę mięśniową gładką, której skurcze są niezależne od woli", "Tworzą ją wyłącznie chrząstki", "Rzęski erytrocytów przesuwają treść"], "correct": 1, "explanation": "W ścianie jelita mięśnie gładkie wykonują ruchy perystaltyczne niezależnie od świadomej decyzji."}, {"no": 9, "question": "Uszkodzona została osłonka mielinowa aksonu, lecz ciało neuronu pozostało całe. Czego należy się spodziewać przede wszystkim?", "topic": "Nerwowa", "options": ["Szybszego przewodzenia impulsów", "Zaburzenia sprawnego przewodzenia impulsów wzdłuż aksonu", "Zwiększenia liczby erytrocytów", "Zamiany aksonu w dendryt"], "correct": 1, "explanation": "Osłonka mielinowa umożliwia szybkie przewodzenie skokowe; jej uszkodzenie może spowolnić lub zaburzyć przekazywanie impulsów."}, {"no": 10, "question": "Sygnał dotarł do zakończenia aksonu. Jak najczęściej przejdzie przez synapsę chemiczną do kolejnej komórki?", "topic": "Nerwowa", "options": ["Przez bezpośredni przepływ hemoglobiny", "Dzięki uwolnieniu neuroprzekaźnika i związaniu go z receptorami komórki odbierającej", "Dzięki ruchom rzęsek nabłonkowych", "Przez krzepnięcie osocza"], "correct": 1, "explanation": "W synapsie chemicznej zakończenie neuronu uwalnia neuroprzekaźnik, który oddziałuje z receptorami następnej komórki."}]'::jsonb);
insert into public.study_tests(id,title,subject,grade,level,path,questions) values('kwasy-v1','Kwasy: HCl, H₂SO₃, H₂CO₃','Chemia','8','','testy/chemia/kwasy.html','[{"no": 1, "question": "Który zestaw poprawnie przyporządkowuje wzory trzem kwasom z kartkówki?", "topic": "Wzory", "options": ["chlorowodorowy HCl; siarkowy(IV) H₂SO₃; węglowy(IV) H₂CO₃", "chlorowodorowy HClO; siarkowy(IV) H₂SO₄; węglowy(IV) H₂CO₃", "chlorowodorowy HCl; siarkowy(IV) H₂SO₄; węglowy(IV) HCO₃", "chlorowodorowy H₂Cl; siarkowy(IV) H₂SO₃; węglowy(IV) CO₂"], "correct": 0, "explanation": "HCl to kwas chlorowodorowy (solny), H₂SO₃ to kwas siarkowy(IV), a H₂CO₃ to kwas węglowy(IV). H₂SO₄ to kwas siarkowy(VI); CO₂ jest tlenkiem, nie kwasem."}, {"no": 2, "question": "Skąd bierze się liczba IV w nazwie „kwas siarkowy(IV)”?", "topic": "Nazewnictwo", "options": ["Oznacza cztery atomy tlenu w cząsteczce.", "Oznacza stopień utlenienia siarki w H₂SO₃.", "Oznacza wartościowość wodoru.", "Oznacza, że kwas oddaje cztery protony."], "correct": 1, "explanation": "W H₂SO₃: 2·(+I) + x + 3·(−II) = 0, więc siarka ma stopień utlenienia +IV. Kwasy H₂SO₃ i H₂CO₃ mają po dwa atomy wodoru."}, {"no": 3, "question": "Jakie równanie opisuje szkolny sposób otrzymywania kwasu siarkowego(IV)?", "topic": "Otrzymywanie", "options": ["SO₃ + H₂O → H₂SO₃", "SO₂ + H₂O ⇌ H₂SO₃", "S + H₂O → H₂SO₃", "SO₂ + O₂ → H₂SO₃"], "correct": 1, "explanation": "Tlenek siarki(IV), SO₂, rozpuszcza się w wodzie i tworzy roztwór kwasu siarkowego(IV). Zapis równowagi przypomina, że ten kwas jest nietrwały."}, {"no": 4, "question": "Uczeń chce otrzymać roztwór kwasu węglowego(IV). Który przebieg doświadczenia jest właściwy?", "topic": "Doświadczenie", "options": ["Przepuszcza CO₂ przez wodę i bada powstały roztwór wskaźnikiem.", "Wsypuje suchy węgiel do wody i ogrzewa.", "Przepuszcza O₂ przez wodę.", "Rozpuszcza CaCO₃ w samej wodzie, zakładając pełną reakcję."], "correct": 0, "explanation": "Rozpuszczenie CO₂ w wodzie prowadzi do równowagi CO₂ + H₂O ⇌ H₂CO₃. Zakwaszenie można wykazać odpowiednim wskaźnikiem; sam węgiel nie tworzy tak kwasu."}, {"no": 5, "question": "Który zapis jest poprawnym równaniem powstawania kwasu węglowego(IV) w wodzie?", "topic": "Równania", "options": ["CO + H₂O → H₂CO₃", "CO₂ + H₂O ⇌ H₂CO₃", "C + 2H₂O → H₂CO₃ + H₂", "CO₂ + H₂ → H₂CO₃"], "correct": 1, "explanation": "Bezwodnikiem kwasu węglowego(IV) jest CO₂. Z wodą pozostaje w równowadze z H₂CO₃, którego w roztworze jest tylko część."}, {"no": 6, "question": "Do probówki z wodą i wskaźnikiem przepuszczono SO₂. Co najlepiej wyjaśnia zmianę barwy wskaźnika na właściwą dla odczynu kwasowego?", "topic": "Doświadczenie", "options": ["SO₂ jest zasadą i bezpośrednio barwi wskaźnik.", "SO₂ reaguje z wodą, a roztwór ma odczyn kwasowy.", "Powstaje kwas siarkowy(VI) H₂SO₄ w wyniku samego dodania wody.", "Wskaźnik reaguje wyłącznie z tlenem z powietrza."], "correct": 1, "explanation": "SO₂ + H₂O ⇌ H₂SO₃. Powstały kwaśny roztwór zmienia barwę wskaźnika. Samo dodanie wody do SO₂ nie daje H₂SO₄."}, {"no": 7, "question": "W doświadczeniu powstawania kwasu węglowego(IV) najlepiej porównać próbkę z CO₂ z próbką kontrolną. Co powinna zawierać kontrola?", "topic": "Doświadczenie", "options": ["Tę samą wodę i wskaźnik, ale bez przepuszczania CO₂.", "Sam czysty CO₂ bez wody.", "Wodę z dużą ilością HCl.", "Roztwór H₂SO₄ zamiast wody."], "correct": 0, "explanation": "Próbka kontrolna różni się tylko badanym czynnikiem, czyli doprowadzeniem CO₂. Dzięki temu zmianę odczynu można powiązać z rozpuszczeniem gazu."}, {"no": 8, "question": "Który opis poprawnie rozróżnia chlorowodór i kwas chlorowodorowy?", "topic": "Właściwości", "options": ["To zawsze dwa różne wzory: chlorowodór HClO, kwas HCl.", "Chlorowodór to gaz HCl, a kwas chlorowodorowy to jego roztwór wodny.", "Chlorowodór to roztwór HCl, a kwas to suchy gaz.", "Chlorowodór jest solą, a kwas chlorowodorowy tlenkiem."], "correct": 1, "explanation": "HCl(g) to gazowy chlorowodór. Po rozpuszczeniu w wodzie otrzymujemy kwas chlorowodorowy, zwyczajowo nazywany kwasem solnym."}, {"no": 9, "question": "Do roztworu kwasu chlorowodorowego dodano wiórki magnezu. Jakie produkty i obserwację przewidujesz?", "topic": "Właściwości", "options": ["MgCl₂ i H₂; pojawiają się pęcherzyki gazu.", "MgO i H₂O; roztwór zamarza.", "MgSO₃ i CO₂; pojawiają się pęcherzyki.", "MgCO₃ i Cl₂; wydziela się zielony gaz."], "correct": 0, "explanation": "Mg + 2HCl → MgCl₂ + H₂↑. Magnez reaguje z kwasem, a wydzielający się wodór widać jako pęcherzyki."}, {"no": 10, "question": "Dlaczego po otwarciu napoju gazowanego część rozpuszczonego CO₂ wydostaje się z cieczy?", "topic": "Właściwości", "options": ["Kwas węglowy jest nietrwały, a spadek ciśnienia sprzyja ulatnianiu CO₂.", "CO₂ zamienia się w tlen wskutek dostępu powietrza.", "H₂CO₃ trwale wiąże cały CO₂ po otwarciu.", "Woda przekształca się w CO₂."], "correct": 0, "explanation": "W zamkniętej butelce większe ciśnienie ułatwia utrzymanie CO₂ w roztworze. Po otwarciu gaz się wydziela; równowaga H₂CO₃ ⇌ CO₂ + H₂O przesuwa się."}, {"no": 11, "question": "Które zestawienie właściwości gazów używanych w doświadczeniach jest poprawne?", "topic": "Właściwości", "options": ["SO₂ jest bezbarwny i ma duszący zapach; CO₂ jest bezbarwny i bezwonny.", "SO₂ jest niebieski i bezwonny; CO₂ ma duszący zapach.", "Oba gazy są barwnymi metalami.", "CO₂ ma intensywny zapach zgniłych jaj, a SO₂ nie rozpuszcza się w wodzie."], "correct": 0, "explanation": "SO₂ jest bezbarwnym gazem o drażniącym, duszącym zapachu; CO₂ jest bezbarwny i bezwonny. SO₂ jest toksyczny — takich gazów nie wącha się bezpośrednio."}, {"no": 12, "question": "Do wody wapiennej wprowadzono CO₂. Najpierw ciecz zmętniała. Co utworzyło osad?", "topic": "Doświadczenie", "options": ["CaCO₃, zgodnie z Ca(OH)₂ + CO₂ → CaCO₃↓ + H₂O", "CaCl₂, zgodnie z Ca(OH)₂ + CO₂ → CaCl₂", "H₂SO₃, zgodnie z CO₂ + SO₂ → H₂SO₃", "C, ponieważ CO₂ rozpada się na węgiel i tlen"], "correct": 0, "explanation": "Białe zmętnienie to wytrącający się węglan wapnia. Ta reakcja służy do wykrywania CO₂; przy nadmiarze CO₂ osad może się następnie rozpuścić."}, {"no": 13, "question": "Które zastosowanie jest najlepiej powiązane z kwasem chlorowodorowym?", "topic": "Zastosowania", "options": ["Usuwanie osadów węglanowych preparatem zawierającym HCl.", "Nasycanie wody CO₂ w napojach gazowanych.", "Bielenie surowców przez SO₂ rozpuszczony w wodzie.", "Produkcja tlenu przez rozkład H₂CO₃."], "correct": 0, "explanation": "HCl reaguje z węglanami, więc bywa składnikiem środków do usuwania kamienia i zapraw. Uwaga praktyczna: nie miesza się takich środków z wybielaczami chlorowymi."}, {"no": 14, "question": "Który opis zastosowania kwasu siarkowego(IV) i związanego z nim SO₂ jest najtrafniejszy?", "topic": "Zastosowania", "options": ["SO₂ i jego roztwory wykorzystywano m.in. do bielenia i konserwowania; gaz wymaga ostrożności.", "H₂SO₃ stosuje się jako trwały, czysty materiał budowlany.", "H₂SO₃ to główny składnik napojów gazowanych.", "SO₂ jest obojętnym gazem używanym do oddychania."], "correct": 0, "explanation": "Roztwory SO₂ mają właściwości m.in. wybielające i hamujące rozwój drobnoustrojów. Kwas H₂SO₃ jest nietrwały, a sam SO₂ drażniący i toksyczny."}, {"no": 15, "question": "Które podsumowanie wszystkich trzech kwasów jest poprawne?", "topic": "Powtórka", "options": ["HCl to kwas beztlenowy, a H₂SO₃ i H₂CO₃ to nietrwałe kwasy tlenowe otrzymywane w szkolnych doświadczeniach przez rozpuszczenie odpowiednich tlenków w wodzie.", "Wszystkie trzy kwasy są beztlenowe i powstają z metali.", "HCl i H₂CO₃ mają identyczny wzór, a H₂SO₃ jest zasadą.", "H₂SO₃ powstaje z CO₂, a H₂CO₃ z SO₂."], "correct": 0, "explanation": "HCl nie zawiera tlenu. H₂SO₃ otrzymuje się z SO₂ i wody, a H₂CO₃ z CO₂ i wody. Oba te kwasy tlenowe są nietrwałe."}]'::jsonb);